/* Power hint helper is tiny; keep it inline but avoid forcing inlining to
 * follow modern BPF verifier guidance. */
static inline u8 current_power_hint(u64 now)
{
	u8 level = power_hint_level;
	if (!level)
		return 0;

	if (now < power_hint_expiry_ns) {
		power_hint_remaining_ns = power_hint_expiry_ns - now;
		return level;
	}

	power_hint_level = 0;
	power_hint_expiry_ns = 0;
	power_hint_remaining_ns = 0;
	return 0;
}

struct slowpath_hint_snapshot {
	u8 power_level;
	bool power_high;
	bool power_medium;
	u32 cache_ccd_count;
	u32 freq_ccd_count;
	u64 frame_interval;
};

static inline struct slowpath_hint_snapshot capture_slowpath_hints(u64 now)
{
	struct slowpath_hint_snapshot snap = {
		.power_level = current_power_hint(now),
		.cache_ccd_count = cache_ccd_cpu_count,
		.freq_ccd_count = freq_ccd_cpu_count,
		.frame_interval = frame_interval_ns,
	};

	snap.power_high = snap.power_level >= 2;
	snap.power_medium = snap.power_level == 1;
	return snap;
}



